import{_ as t,c as e,a2 as a,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二百四十六章 无法被推测","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/246第二百四十六章 无法被推测.md","filePath":"meditation/巴利文大藏经/246第二百四十六章 无法被推测.md"}'),r={name:"meditation/巴利文大藏经/246第二百四十六章 无法被推测.md"};function _(n,p,i,s,d,c){return o(),e("div",null,p[0]||(p[0]=[a('<h1 id="第二百四十六章-无法被推测" tabindex="-1">第二百四十六章 无法被推测 <a class="header-anchor" href="#第二百四十六章-无法被推测" aria-label="Permalink to &quot;第二百四十六章 无法被推测&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部22相应36经/某位比丘经第二(蕴相应/蕴篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，有一位出家人来到佛陀的住所，他顶礼佛陀后，就在一旁坐下，他对佛陀说：“世尊，请您简要的教导我，让我听闻您说法后，能够独自清净的修行，能够由此管束好自己的行为、言语、念想，让我不胡思乱想，不胡作非为，让我的内心能够长时间的保持清净，让我能够精进努力的按您的正法去修行。世尊，如果您为我说的法能够让我这样的话，那就很好了。”</p><p>佛陀说：“比丘！有执着和挂念，有烦恼的产生，就能被推测、揣测，能够被推测、揣测就会被命名，就会被安立名称，什么是被命名和被安立名称呢？就是会用一些名字、词语来描述形容这些执着、挂念、烦恼的状态，比如贪爱美女，就会被描述为好色；贪爱快乐的感受，就会被描述为享乐；贪爱念想、思想，就会被描述为幻想、梦想；贪爱各种行为就会被描述为行动、主动、抢夺；贪爱认识、分别、判断就会被描述为鉴别、犹豫、果断。</p><p>比丘！没有执着和挂念，没有烦恼的产生，就无法被推测、揣测，无法被推测、揣测就不会被命名，就不会被安立名称，就无法用一些名字、词语来描述形容当前的状态，就处于无法描述，没有名字的状态。”</p><p>这位出家人说到：“世尊，我已经明白了，感谢世尊您为我说法。”</p><p>佛陀说：“比丘！如来刚才只是简要的讲说了一下法理，你已经明白了吗？如来刚才讲说的法义你能详细的描述一下吗？”</p><p>这位出家弟子回答：“世尊，如果对物质事物、物质身体生起了烦恼；执着和挂念物质事物、物质身体，那么就能被推测、揣测，既然能够被推测、揣测，就会被命名，就会被安立名称，比如贪爱物质事物，就会被描述为贪得无厌，贪爱物质身体会被描述为沉溺美色。</p><p>如果对感受、念想、行为、认识、分别、判断生起了烦恼；执着和挂念感受、念想、行为、认识、分别、判断，那么就能被推测、揣测，既然能够被推测、揣测，就会被命名，就会被安立名称，比如贪爱快乐的感受，就会被描述为寻欢作乐；贪爱念想、思想就会被描述为异想天开；贪爱行为就会被描述为肆意妄为；贪爱认识、分别、判断就会被描述为优柔寡断。</p><p>世尊，如果不对物质事物、物质身体、感受、念想、行为、认识、分别、判断生起烦恼；不执着和挂念物质事物、物质身体、感受、念想、行为、认识、分别、判断，那么就无法被推测、揣测，既然无法被推测、揣测，就不会被命名，就不会被安立名称，就无法用一些名字、词语来描述形容当前的状态，就处于无法描述，没有名字的状态。”</p><p>佛陀说：“比丘！很好！很好！你已经完全明白如来所说的法义。”</p><p>佛陀说法后，这位出家人再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他站起来向右围绕着佛陀转圈，以此表示他对佛陀的最高敬意，之后他就离开了。</p><p>这位出家人，他按着佛陀所说的正法独自的去修行，他管束好了自己的行为、言语、念想，不让自己胡思乱想、胡作非为，他让自己的内心安住在清净的境界之中，不让自己产生能被推测、揣测，会被命名、安立名称的烦恼、执着、挂念，没有过多久，这位出家人他就开启了解脱的智慧，他就证悟了解脱的果位，他自己彻底明白：「从这一世开始已经不会再出生在世间了。行为、言语、念想的修行已经圆满，应该做的事情已经做好，不会再有喜怒哀乐等等烦恼和痛苦的轮回状态了，不会再出生的世间了，已经彻底从生死轮回中解脱出来。」</p><p>这位出家人成为了佛陀阿罗汉弟子中的一员。</p>',15)]))}const f=t(r,[["render",_]]);export{m as __pageData,f as default};
